   "type": "사료 탐정",
   "prompt": "1982년 3월 27일 개막전(MBC 청룡 대 삼성 라이온즈)에서 MBC 이종도가 끝내기 만루홈런을 쳤어요. 그런데 기록마다 홈런이 나온 이닝이 달라요. 아래 사료 카드 네 장을 읽고, 어느 기록을 믿어야 할지 골라 보세요.",
