   "prompt": "해태 타이거즈의 모기업은 과자를 만드는 해태제과였어요. 아래 사료 카드 두 장을 함께 읽고, 1980년대 과자·껌·맥주 회사들이 야구단에 회사나 상품 이름을 붙인 까닭으로 가장 알맞은 것을 골라 보세요.",
