   "explain": "OB가 맥주 이름을 팀명에 붙여 친근한 이미지를 노렸듯, 기업들은 야구 인기를 회사와 상품 홍보에 활용했어요. 거꾸로 입장료로 돈을 버는 사업은 아니었어요. 2000년대 초반까지도 구단 수입의 70% 이상이 입장료였고, 구단 운영은 수익성이 낮은 사업이었어요(토스피드). 그래서 기업에게 야구단은 '돈 버는 곳'보다 '이름을 알리는 곳'에 가까웠어요.",
